using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;

[McpServerToolType]
public static class ApiFetchTool
{
    /// <summary>Fetches data from an external API and returns the JSON response.</summary>
    [McpServerTool, Description("Fetches JSON data from a given URL via HTTP GET.")]
    public static async Task<string> FetchJson(
        IHttpClientFactory httpClientFactory,
        [Description("The full URL to fetch.")] string url,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("default");
        var response = await client.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerPromptType]
public static class SummarizePrompt
{
    /// <summary>Returns a prompt that asks the model to summarize the given text.</summary>
    [McpServerPrompt, Description("Summarize text into concise bullet points.")]
    public static IList<Microsoft.Extensions.AI.ChatMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Maximum number of bullet points.")] int maxPoints = 5)
    {
        return
        [
            new(Microsoft.Extensions.AI.ChatRole.User,
                $"""
                Summarize the following text into at most {maxPoints} concise bullet points.

                Text:
                {text}
                """)
        ];
    }
}

